function owner(input=source){const file={path:'Catalog.base',extension:'base'},saved={file:{path:file.path},content:input,version:'v1',hasBom:true},state={writable:true,current:true,root:'root',actual:saved,saved,calls:[],read:null,save:null},app={changingVault:false,workspace:{isChangingFiles:false},core:{async run(fn){return fn()}},vault:{get rootPath(){return state.root},getFileByPath:path=>path===file.path?file:null,assertWritable(){if(!state.writable)throw Error('read-only')},async readDocument(path){state.calls.push({read:path});if(state.read)await state.read();return state.actual}}},authority={current:()=>state.current,savedSource:()=>state.saved,closed(){},async save(plan){state.calls.push({save:plan});if(state.save)await state.save()}};return{app,file,state,authority,review:()=>new Review(app,file,input,'Table',draft(input,{rowHeight:'extra'}),authority)}}
test('Apply proves exact physical source/version/BOM and delegates one immutable plan once',async()=>{const o=owner(),r=o.review();assert.deepEqual(o.state.calls,[]);await r.apply();assert.equal(r.completed,true);assert.equal(r.applying,false);assert.deepEqual(o.state.calls.map(c=>Object.keys(c)[0]),['read','save']);assert.equal(o.state.calls[1].save,r.plan);await assert.rejects(r.apply(),/already applied/)});
test('Read-only, canceled, renamed, replaced and obsolete owners refuse before any authoring IO',async()=>{for(const kind of['readonly','current','root','version','content','bom','path','extension','switch','transition','closed']){const o=owner(),r=o.review();if(kind==='readonly')o.state.writable=false;if(kind==='current')o.state.current=false;if(kind==='root')o.state.root='new';if(kind==='version')o.state.saved={...o.state.saved,version:'v2'};if(kind==='content')o.state.saved={...o.state.saved,content:source+'x'};if(kind==='bom')o.state.saved={...o.state.saved,hasBom:false};if(kind==='path')o.file.path='Else.base';if(kind==='extension')o.file.extension='md';if(kind==='switch')o.app.changingVault=true;if(kind==='transition')o.app.workspace.isChangingFiles=true;if(kind==='closed')r.close();await assert.rejects(r.apply(),/read-only|changed/);assert.deepEqual(o.state.calls,[]);assert.equal(r.attempted,false)}});
test('Physical BOM-only, source, path and version conflicts and held owner changes refuse before save',async()=>{for(const replacement of[{version:'v2'},{content:source+'\n'},{file:{path:'Other.base'}},{hasBom:false}]){const o=owner(),r=o.review();o.state.actual={...o.state.actual,...replacement};await assert.rejects(r.apply(),/changed on disk/);assert.deepEqual(o.state.calls,[{read:'Catalog.base'}]);assert.equal(r.attempted,false)}for(const invalidate of[o=>o.state.current=false,(_o,r)=>r.close(),o=>o.state.root='other',o=>o.state.writable=false]){const o=owner(),r=o.review();o.state.read=async()=>invalidate(o,r);await assert.rejects(r.apply(),/changed|read-only/);assert.deepEqual(o.state.calls,[{read:'Catalog.base'}])}});
test('An unconfirmed save consumes its review and keeps failure status distinct from completion',async()=>{const o=owner(),r=o.review();o.state.save=async()=>{throw Error('unconfirmed')};await assert.rejects(r.apply(),/unconfirmed/);assert.equal(r.attempted,true);assert.equal(r.completed,false);assert.equal(r.applying,false);await assert.rejects(r.apply(),/already applied/);assert.equal(o.state.calls.length,2)});

